import { nextTick, onMounted, ref, type Ref } from 'vue'

/**
 * One block for a whole list (useGlideMark.ts, the website's Product menu highlight): it glides on transform to the row
 * under the pointer or focus, and rests on the current row (`rest`) when the pointer leaves, or hides when there is
 * none. Rows are the list's [data-glide-row] elements, in order, each positioned relative to the list. The first
 * placement doesn't glide. Draw the block with GlideMark.
 */
export function useGlideMark(list: Ref<HTMLElement | null>, rest: () => number | null) {
  const mark = ref<{ y: number, h: number } | null>(null)
  const shown = ref(false)
  const instant = ref(true)
  const hot = ref<number | null>(null)

  function place(i: number | null, instantly: boolean) {
    const row = i === null ? undefined : list.value?.querySelectorAll<HTMLElement>('[data-glide-row]')[i]
    if (!row) {
      shown.value = false
      hot.value = null
      return
    }
    instant.value = instantly
    mark.value = { y: row.offsetTop, h: row.offsetHeight }
    shown.value = true
    hot.value = i
  }

  const point = (i: number) => place(i, !shown.value)
  const leave = () => place(rest(), false)
  const settle = () => place(rest(), true)

  onMounted(() => nextTick(settle))

  return { mark, shown, instant, hot, point, leave, settle }
}

// The gliding block itself (console2.css .v2-rowmark): the paper behind the row useGlideMark points at, moving on
// transform and height in 200ms on the strong ease-out, and placed without a glide the first time. Put it first inside
// the list (which is position: relative) and give the rows a z-index above it. Reduced motion places it at once.
export interface GlideMarkProps {
  mark: { y: number, h: number } | null
  instant?: boolean
}

export function GlideMark({ mark, instant }: GlideMarkProps) {
  if (!mark) return null
  return (
    <>
      <style href="ds-glide-mark" precedence="ds">{css}</style>
      <span data-ds="glide-mark" className="ds-rowmark" data-instant={instant || undefined} style={{ transform: `translateY(${mark.y}px)`, height: `${mark.h}px` }} aria-hidden="true" />
    </>
  )
}

export default GlideMark

const css = `
.ds-rowmark { position: absolute; top: 0; right: 0; left: 0; z-index: 0; background: var(--ds-color-surface-subtle); pointer-events: none; transition: transform var(--ds-duration-enter) var(--ds-easing-out), height var(--ds-duration-enter) var(--ds-easing-out); }
.ds-rowmark[data-instant] { transition: none; }
@media (prefers-reduced-motion: reduce) { .ds-rowmark { transition: none; } }
`

'use client'
import { useCallback, useEffect, useRef, useState, type RefObject } from 'react'

/**
 * One block for a whole list (useGlideMark.ts, the website's Product menu highlight): it glides on transform to the row
 * under the pointer or focus, and rests on the current row (`rest`) when the pointer leaves, or hides when there is
 * none. Rows are the list's [data-glide-row] elements, in order, each positioned relative to the list. The first
 * placement doesn't glide. Draw the block with GlideMark.
 */
export function useGlideMark(list: RefObject<HTMLElement | null>, rest: () => number | null) {
  const [mark, setMark] = useState<{ y: number, h: number } | null>(null)
  const [shown, setShown] = useState(false)
  const [instant, setInstant] = useState(true)
  const [hot, setHot] = useState<number | null>(null)
  // What place() reads straight after a change, as Vue's refs give it.
  const shownNow = useRef(false)
  const restRef = useRef(rest)
  restRef.current = rest

  const place = useCallback((i: number | null, instantly: boolean) => {
    const row = i === null ? undefined : list.current?.querySelectorAll<HTMLElement>('[data-glide-row]')[i]
    if (!row) {
      shownNow.current = false
      setShown(false)
      setHot(null)
      return
    }
    setInstant(instantly)
    setMark({ y: row.offsetTop, h: row.offsetHeight })
    shownNow.current = true
    setShown(true)
    setHot(i)
  }, [list])

  const point = useCallback((i: number) => place(i, !shownNow.current), [place])
  const leave = useCallback(() => place(restRef.current(), false), [place])
  const settle = useCallback(() => place(restRef.current(), true), [place])

  useEffect(() => settle(), [settle])

  return { mark, shown, instant, hot, point, leave, settle }
}

